const input = $input.item.json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const required = [
  'transaction_id','user_id','amount','currency','merchant',
  'timestamp','location','device','payment_method'
];

const missing = required.filter(k => body[k] === undefined || body[k] === null || body[k] === '');
const errors = [];

const amount = Number(body.amount);
if (!Number.isFinite(amount) || amount < 0) {
  errors.push('amount must be a non-negative number');
}

const date = new Date(body.timestamp);
if (Number.isNaN(date.getTime())) {
  errors.push('timestamp must be a valid ISO-8601 date');
}

if (!body.location || typeof body.location !== 'object') {
  errors.push('location must be an object');
}
if (!body.device || typeof body.device !== 'object') {
  errors.push('device must be an object');
}

const valid = missing.length === 0 && errors.length === 0;

return [{
  json: {
    valid,
    errors: [...missing.map(k => `Missing required field: ${k}`), ...errors],
    transaction: body,
    received_at: new Date().toISOString()
  }
}];

const t = $('Validate Transaction').first().json.transaction || {};
const amount = Number(t.amount) || 0;
const previousAverage = Number(t.previous_average_amount);
const previousCount = Number(t.previous_transaction_count) || 0;
const accountAgeDays = Number(t.account_age_days);
const device = t.device || {};
const location = t.location || {};
const method = String(t.payment_method || '').toUpperCase();

const multiplier = Number.isFinite(previousAverage) && previousAverage > 0
  ? amount / previousAverage
  : null;

const flags = [];
const reasons = [];
let ruleScore = 0;

if (multiplier !== null && multiplier >= 5) {
  ruleScore += 20;
  flags.push('HIGH_AMOUNT');
  reasons.push(`Amount is ${multiplier.toFixed(1)}x the historical average`);
}
if (multiplier !== null && multiplier >= 10) {
  ruleScore += 20;
  flags.push('EXTREME_AMOUNT');
  reasons.push('Transaction amount is extremely abnormal');
}
if (Number.isFinite(accountAgeDays) && accountAgeDays < 7) {
  ruleScore += 20;
  flags.push('NEW_ACCOUNT');
  reasons.push('Account is less than 7 days old');
}
if (previousCount >= 20 || t.high_frequency === true) {
  ruleScore += 15;
  flags.push('HIGH_VELOCITY');
  reasons.push('Unusually high recent transaction frequency');
}
if (device.new_device === true || device.is_known === false) {
  ruleScore += 20;
  flags.push('NEW_DEVICE');
  reasons.push('Transaction originated from an unfamiliar device');
}
if (location.unusual_location === true || location.is_usual === false) {
  ruleScore += 20;
  flags.push('LOCATION_ANOMALY');
  reasons.push('Location differs from normal activity');
}
if (['CRYPTO','GIFT_CARD','WIRE','WIRE_TRANSFER'].includes(method)) {
  ruleScore += 10;
  flags.push('PAYMENT_METHOD_RISK');
  reasons.push('Payment method has elevated abuse risk');
}
if (flags.length >= 3) ruleScore += 10;
ruleScore = Math.min(100, ruleScore);

/*
  Incident intelligence:
  Pass an optional recent_transactions array in the webhook payload.
  This lets the workflow work standalone for demos and tests. In production,
  replace this array with a database/stream lookup for the merchant's recent
  transactions.
*/
const recent = Array.isArray(t.recent_transactions) ? t.recent_transactions : [];
const baselineFraudRate = Math.min(
  0.50,
  Math.max(0.001, Number(t.baseline_fraud_rate ?? 0.01))
);

function transactionSuspicion(x) {
  if (!x || typeof x !== 'object') return 0;
  let s = 0;
  const a = Number(x.amount);
  const avg = Number(x.previous_average_amount);
  if (Number.isFinite(avg) && avg > 0 && Number.isFinite(a)) {
    const m = a / avg;
    if (m >= 5) s += 25;
    if (m >= 10) s += 20;
  }
  if (Number(x.account_age_days) < 7) s += 15;
  if (x.high_frequency === true || Number(x.previous_transaction_count) >= 20) s += 15;
  if (x.device?.new_device === true || x.device?.is_known === false) s += 20;
  if (x.location?.unusual_location === true || x.location?.is_usual === false) s += 20;
  if (['CRYPTO','GIFT_CARD','WIRE','WIRE_TRANSFER'].includes(String(x.payment_method || '').toUpperCase())) s += 10;
  return Math.min(100, s);
}

const suspiciousScores = recent.map(transactionSuspicion);
const suspiciousCount = suspiciousScores.filter(s => s >= 60).length;
const recentCount = recent.length;
const suspiciousRate = recentCount ? suspiciousCount / recentCount : 0;
const spikeRatio = baselineFraudRate > 0 ? suspiciousRate / baselineFraudRate : 0;

const deviceCounts = {};
const beneficiaryCounts = {};
const ipCounts = {};
for (const x of recent) {
  const did = x?.device?.device_id;
  const bid = x?.beneficiary_id;
  const ip = x?.ip_address;
  if (did) deviceCounts[did] = (deviceCounts[did] || 0) + 1;
  if (bid) beneficiaryCounts[bid] = (beneficiaryCounts[bid] || 0) + 1;
  if (ip) ipCounts[ip] = (ipCounts[ip] || 0) + 1;
}
const maxDeviceCluster = Math.max(0, ...Object.values(deviceCounts));
const maxBeneficiaryCluster = Math.max(0, ...Object.values(beneficiaryCounts));
const maxIPCluster = Math.max(0, ...Object.values(ipCounts));

let incidentScore = 0;
const incidentReasons = [];
if (recentCount >= 10 && suspiciousRate >= 0.05) {
  incidentScore += 30;
  incidentReasons.push(`Suspicious transaction rate is ${(suspiciousRate*100).toFixed(1)}%`);
}
if (recentCount >= 10 && spikeRatio >= 3) {
  incidentScore += 25;
  incidentReasons.push(`Suspicious activity is ${spikeRatio.toFixed(1)}x the baseline`);
}
if (maxDeviceCluster >= 4) {
  incidentScore += 15;
  incidentReasons.push(`A device is shared across ${maxDeviceCluster} recent transactions`);
}
if (maxBeneficiaryCluster >= 4) {
  incidentScore += 20;
  incidentReasons.push(`A beneficiary is linked to ${maxBeneficiaryCluster} recent transactions`);
}
if (maxIPCluster >= 5) {
  incidentScore += 10;
  incidentReasons.push(`An IP address appears in ${maxIPCluster} recent transactions`);
}
incidentScore = Math.min(100, incidentScore);

let riskLevel = 'LOW';
let decision = 'APPROVE';
if (ruleScore >= 60) {
  riskLevel = 'HIGH';
  decision = 'BLOCK';
} else if (ruleScore >= 30) {
  riskLevel = 'MEDIUM';
  decision = 'REVIEW';
}
if (ruleScore >= 85) {
  riskLevel = 'CRITICAL';
  decision = 'BLOCK';
}

let incidentSeverity = 'NONE';
if (incidentScore >= 80) incidentSeverity = 'CRITICAL';
else if (incidentScore >= 60) incidentSeverity = 'HIGH';
else if (incidentScore >= 40) incidentSeverity = 'MEDIUM';

const incidentDetected = incidentScore >= 60;
const incidentId = incidentDetected
  ? `INC-${new Date().toISOString().replace(/\D/g,'').slice(0,14)}-${String(Math.floor(Math.random()*10000)).padStart(4,'0')}`
  : null;

const potentialExposure = incidentDetected
  ? recent.filter((x, i) => suspiciousScores[i] >= 60)
      .reduce((sum, x) => sum + (Number(x.amount) || 0), 0)
  : 0;

const finalReasons = [...reasons, ...incidentReasons];

return [{
  json: {
    transaction_id: t.transaction_id,
    transaction: t,
    risk_score: ruleScore,
    risk_level: riskLevel,
    decision,
    fraud_probability: Number((ruleScore / 100).toFixed(2)),
    rule_flags: flags,
    reasons: finalReasons,
    incident: {
      detected: incidentDetected,
      incident_id: incidentId,
      severity: incidentSeverity,
      incident_score: incidentScore,
      recent_transaction_count: recentCount,
      suspicious_transaction_count: suspiciousCount,
      suspicious_rate: Number(suspiciousRate.toFixed(4)),
      baseline_fraud_rate: baselineFraudRate,
      spike_ratio: Number(spikeRatio.toFixed(2)),
      max_device_cluster: maxDeviceCluster,
      max_beneficiary_cluster: maxBeneficiaryCluster,
      max_ip_cluster: maxIPCluster,
      affected_transactions: suspiciousCount,
      potential_exposure: potentialExposure
    },
    explanation: finalReasons.length
      ? `Transaction risk ${ruleScore}/100. ${finalReasons.join('; ')}.`
      : 'No significant rule-based fraud indicators were detected.',
    next_action: incidentDetected
      ? 'Open the fraud incident, review the affected cluster, and require human approval for containment actions.'
      : decision === 'REVIEW'
        ? 'Send to manual review.'
        : decision === 'BLOCK'
          ? 'Block or hold according to merchant risk policy.'
          : 'Allow and continue monitoring.'
  }
}];
